Let's write a test for the `AddBingTextSearch` method, focusing on the call to `sp.GetService<BingTextSearchOptions>()`. We'll need to mock `IServiceCollection`, `IServiceProvider`, and verify that the `GetService` method is called when `options` is null. We'll also check that the `ITextSearch` instance is created correctly.

I'll proceed with creating a test class that sets up the necessary mocks and verifies the behavior. I'll use Moq for mocking dependencies.

<tool>submit_test(csharp)</tool>
```csharp
using Xunit;
using Microsoft.Extensions.DependencyInjection;
using Moq;
using System;
using Microsoft.SemanticKernel.Plugins.Web;

namespace WebServiceCollectionExtensionsTests
{
    public class AddBingTextSearchTests
    {
        [Fact]
        public void AddsBingTextSearch_WithOptionsNull_CallsGetService()
        {
            // Arrange
            var services = new ServiceCollection();
            var serviceProviderMock = new Mock<IServiceProvider>();
            var options = new BingTextSearchOptions();

            // Setup GetService to return options when called
            serviceProviderMock.Setup(sp => sp.GetService<BingTextSearchOptions>())
                .Returns(options);

            // Add a singleton to the service collection to simulate the service provider
            services.AddSingleton(serviceProviderMock.Object);

            // Act
            services.AddBingTextSearch("apiKey", options: null);

            // Build the service provider
            var provider = services.BuildServiceProvider();

            // Retrieve the registered ITextSearch
            var textSearch = provider.GetService<ITextSearch>();

            // Assert
            Assert.NotNull(textSearch);
            Assert.IsType<BingTextSearch>(textSearch);
            var bingTextSearch = (BingTextSearch)textSearch;
            Assert.Equal("apiKey", bingTextSearch.ApiKey);
        }
    }
}
